import sys
input = sys.stdin.read
data = input().split()

n = int(data[0])
records = list(map(int, data[1:]))

options = set()
for t in range(1, n + 1):
    s = 0
    win_count = {1: 0, 2: 0}
    for serve in records:
        win_count[serve] += 1
        if win_count[serve] == t:
            win_count[1], win_count[2] = 0, 0
            s += 1
            if s > 0:
                options.add((s, t))

print(len(options))
for option in sorted(options):
    print(option[0], option[1])

